<?php
namespace App\Http\Controllers;
use App\Models\{Venue,VenueMailAccount,MailNotification};use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class MailSettingsController extends Controller {
 private function own(Request $r,Venue $v){abort_unless($v->owner_account_id===$r->user()->id,403);}
 public function show(Request $r,Venue $venue){$this->own($r,$venue);$a=VenueMailAccount::where('venue_id',$venue->id)->first();return ['account'=>$a?array_merge($a->toArray(),['configured'=>array_keys(array_filter($a->credentials??[])),'smtp'=>array_intersect_key($a->credentials??[],array_flip(['host','port','username']))]):null,'smtp_hosts'=>config('notifications.smtp_hosts')];}
 public function save(Request $r,Venue $venue){$this->own($r,$venue);$d=$r->validate(['provider'=>['required',Rule::in(['resend','postmark','smtp'])],'enabled'=>'required|boolean','from_email'=>'required|email|max:254','from_name'=>['required','string','max:100','not_regex:/[\r\n<>]/'],'reply_to'=>'nullable|email|max:254','credentials'=>'present|array:api_key,host,port,username,password','credentials.api_key'=>'nullable|string|max:3000','credentials.host'=>['nullable',Rule::in(config('notifications.smtp_hosts'))],'credentials.port'=>'nullable|integer|in:465,587','credentials.username'=>'nullable|string|max:254','credentials.password'=>'nullable|string|max:3000']);$a=VenueMailAccount::firstOrNew(['venue_id'=>$venue->id]);$credentials=$a->provider===$d['provider']?($a->credentials??[]):[];foreach($d['credentials'] as $k=>$value)if(filled($value))$credentials[$k]=$value;if($d['enabled'])foreach($d['provider']==='smtp'?['host','port','username','password']:['api_key'] as $k)abort_unless(filled($credentials[$k]??null),422,'Completa las credenciales del proveedor de correo.');$a->fill(collect($d)->except('credentials')->all());$a->credentials=$credentials;$a->save();return $this->show($r,$venue);}
 public function history(Request $r,Venue $venue){$this->own($r,$venue);return MailNotification::where('venue_id',$venue->id)->orderByDesc('created_at')->paginate(30)->through(fn($n)=>array_merge($n->toArray(),['order'=>$n->payload['order'],'recipient'=>$n->payload['to']]));}
 public function retry(Request $r,Venue $venue,MailNotification $notification){$this->own($r,$venue);abort_unless($notification->venue_id===$venue->id,404);abort_unless(in_array($notification->status,['failed','blocked']),422,'Un envío aceptado o incierto no se repite automáticamente.');abort_unless(MailNotification::whereKey($notification->id)->whereIn('status',['failed','blocked'])->update(['status'=>'pending','error'=>null,'updated_at'=>now()]),422,'El correo ya cambió de estado. Actualiza la bandeja.');return ['ok'=>true];}
}
